  const adjustments=salesEvents.filter(event=>event.source==='adjustment').slice().reverse().slice(0,20);document.querySelector('#manual-adjustments').innerHTML=adjustments.length?adjustments.map(event=>`<div class="manual-adjustment"><div><b>${escapeHTML(event.name)}</b><small>${escapeHTML(event.note||'Correction manuelle')} · ${new Date(event.date).toLocaleString('fr-FR',{weekday:'short',hour:'2-digit',minute:'2-digit'})}</small></div><strong>${event.revenue>=0?'+':''}${format(event.revenue)}</strong><button type="button" data-adjust-delete="${event.id}">Annuler</button></div>`).join(''):'<div class="team-empty">Aucune correction manuelle cette semaine</div>';
  document.querySelector('#service-history-count').textContent=`${services.history.length} rapport${services.history.length>1?'s':''}`;
