  document.querySelector('#service-history').innerHTML=services.history.length?services.history.map(service=>{const report=service.snapshot||{},net=Number(report.revenue||0)-Number(report.expenses_total||0),hourly=Array.isArray(report.hourly)?report.hourly:[];return `<details class="service-report"><summary><div><b>${escapeHTML(service.name)}</b><small>${new Date(service.closedAt).toLocaleDateString('fr-FR')} · ${report.duration_minutes?formatDuration(Number(report.duration_minutes)*60000)+' · ':''}fermé par ${escapeHTML(service.closedBy||'—')}</small></div><strong>${format(net)}</strong></summary><div class="service-report-detail"><span><small>Encaissé</small><b>${format(report.revenue||0)}</b></span><span><small>Articles</small><b>${report.items||0}</b></span><span><small>Commandes</small><b>${report.orders||0}</b></span><span><small>Dépenses</small><b>${format(report.expenses_total||0)}</b></span><span><small>Argent offert</small><b>${format(report.gift_money||0)}</b></span><span><small>Consos offertes</small><b>${report.gift_drinks||0}</b></span>${hourly.length?`<div class="service-report-hourly"><div class="hourly-chart">${(()=>{const max=Math.max(...hourly.map(x=>Number(x.revenue)),1);return hourly.map(x=>`<span class="chart-column"><b>${format(Number(x.revenue))}</b><i class="chart-bar" style="height:${Math.max(3,Number(x.revenue)/max*42)}px"></i><small>${String(x.hour).padStart(2,'0')}h</small></span>`).join('')})()}</div></div>`:''}</div></details>`}).join(''):'<div class="team-empty">Aucun rapport clôturé</div>';
