function getExportReport(){if(services.current)return{name:services.current.name,report:{revenue:teamStats.reduce((s,x)=>s+x.revenue,0),items:teamStats.reduce((s,x)=>s+x.items,0),orders:teamStats.reduce((s,x)=>s+x.orders,0),expenses_total:expenses.reduce((s,x)=>s+x.amount,0),team:teamStats,expenses}};const last=services.history[0];return last?{name:last.name,report:last.snapshot||{}}:null}
function downloadServiceCSV(){const source=getExportReport();if(!source)return toast('Aucun rapport disponible');const r=source.report,rows=[['Rapport',source.name],['Encaissé',r.revenue||0],['Articles',r.items||0],['Commandes',r.orders||0],['Dépenses',r.expenses_total||0],[],['Employé','Encaissé','Articles','Commandes'],...(r.team||[]).map(x=>[x.name,x.revenue,x.items,x.orders]),[],['Dépense','Catégorie','Montant','Employé'],...(r.expenses||[]).map(x=>[x.label,x.category,x.amount,x.operator])],csv='\ufeff'+rows.map(row=>row.map(value=>`"${String(value??'').replace(/"/g,'""')}"`).join(';')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=`rapport-${source.name.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}.csv`;link.click();URL.revokeObjectURL(url)}

function renderRaffle(){const sold=raffle.entries.reduce((s,x)=>s+x.tickets,0);document.querySelector('#raffle-pot').textContent=format(sold*raffle.price);document.querySelector('#raffle-sold').textContent=sold;document.querySelector('#raffle-max-label').textContent=raffle.max;document.querySelector('#ticket-price').value=raffle.price;document.querySelector('#ticket-max').value=raffle.max;document.querySelector('#raffle-count').textContent=`${raffle.entries.length} participant${raffle.entries.length>1?'s':''}`;document.querySelector('#raffle-winner').querySelector('strong').textContent=raffle.winner||'Pas encore tiré';document.querySelector('#raffle-list').innerHTML=raffle.entries.length?raffle.entries.map(x=>`<li><span class="history-icon">🎟</span><span class="history-info"><b>${x.name}</b><small>Ajouté par ${x.operator}</small></span><span class="history-amount">${x.tickets} ticket${x.tickets>1?'s':''}</span></li>`).join(''):'<li class="empty">Aucun participant pour le moment</li>';updateRaffleCost()}
