function renderPreviousWinners(){
  document.querySelector('#reset-game-winners').hidden=!isAdminName(operatorName);
  document.querySelector('#previous-winners').innerHTML=game.winnersError?'<div class="team-empty winners-error">Historique non installé dans Supabase</div>':game.winners.length?game.winners.map(game=>{const podium=[game.first,game.second,game.third].filter(x=>x.name),all=game.standings.length?game.standings:podium;return `<details class="previous-winner"><summary><small>Partie · toucher pour ouvrir</small><b>🏆 ${escapeHTML(game.title)}</b><ol class="winner-podium">${podium.map((player,index)=>`<li><em>${['🥇','🥈','🥉'][index]}</em><span>${escapeHTML(player.name)}</span><strong>${player.points} pt</strong></li>`).join('')}</ol></summary><div class="full-game-ranking"><small>Classement complet · ${all.length} joueur${all.length>1?'s':''}</small><ol>${all.map((player,index)=>`<li><em>${index+1}</em><span>${escapeHTML(player.name)}</span><strong>${player.points} pt</strong></li>`).join('')}</ol>${isAdminName(operatorName)?`<button class="delete-archived-game" data-delete-game="${game.id}" type="button">Supprimer cette partie</button>`:''}</div></details>`}).join(''):'<div class="team-empty">Aucune partie terminée avec des points</div>'
}

function renderOrderLogs(){
  const revenue=savedOrders.reduce((sum,order)=>sum+order.total,0),itemCount=savedOrders.reduce((sum,order)=>sum+order.items.length,0);
  const shared=teamStats.find(person=>person.name.toLowerCase()===operatorName.toLowerCase());
  document.querySelector('#order-revenue').textContent=format(shared?shared.revenue:revenue);
  document.querySelector('#order-items').textContent=format(shared?shared.items:itemCount);
  document.querySelector('#order-count').textContent=format(shared?shared.orders:savedOrders.length);
  document.querySelector('#saved-orders-count').textContent=`${savedOrders.length} commande${savedOrders.length>1?'s':''}`;
  const products=new Map();savedOrders.forEach(order=>order.items.forEach(item=>{const label=item.logName||item.name,old=products.get(label)||{qty:0,total:0};old.qty++;old.total+=item.amount;products.set(label,old)}));
  document.querySelector('#sales-summary').innerHTML=products.size?[...products.entries()].sort((a,b)=>b[1].qty-a[1].qty).map(([name,data])=>`<li><span>${name}</span><b>${data.qty} · ${format(data.total)}</b></li>`).join(''):'<li class="empty">Aucune vente</li>';
  document.querySelector('#order-history').innerHTML=savedOrders.length?savedOrders.slice(0,50).map(order=>{const grouped=new Map();order.items.forEach(item=>{const label=item.logName||item.name;grouped.set(label,(grouped.get(label)||0)+1)});const detail=[...grouped.entries()].map(([name,qty])=>`${qty} × ${name}`).join(', ');return `<li><span class="history-icon">✓</span><span class="history-info"><b>${escapeHTML(detail)}</b><small>${order.source==='ardoise'?'Ardoise · ':''}${escapeHTML(order.operator||'Sans nom')} · ${new Date(order.date).toLocaleString('fr-FR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</small></span><span class="history-amount">${format(order.total)}</span>${order.source!=='ardoise'?`<button class="log-delete" data-order-cancel="${order.date}" type="button" title="Annuler cette commande">×</button>`:''}</li>`}).join(''):'<li class="empty">Aucune commande enregistrée</li>';
}
function renderTeamStats(){const admin=isAdminName(operatorName),html=teamStats.length?teamStats.map((person,index)=>`<div class="team-member"><span class="team-member-head"><b>${escapeHTML(person.name)}${isAdminName(person.name)?'<em class="team-admin-label">ADMIN</em>':''}</b>${admin&&person.name.toLowerCase()!==operatorName.toLowerCase()?`<button class="admin-reset-member" data-team-reset="${index}" type="button">Mettre à zéro</button>`:''}</span><div><span><small>Encaissé</small><strong>${format(person.revenue)}</strong></span><span><small>Articles</small><strong>${person.items}</strong></span><span><small>Commandes</small><strong>${person.orders}</strong></span></div></div>`).join(''):'<div class="team-empty">Aucun total partagé pour le moment</div>';document.querySelectorAll('.team-stats').forEach(container=>container.innerHTML=html)}
async function syncPersonalStats(revenue,items,orders){if(!db||!operatorName)return;await db.rpc('fermer_service_si_inactif');const{error}=await db.rpc('ajouter_stats_personnelles',{p_operator_name:operatorName,p_revenue:revenue,p_items:items,p_orders:orders});if(error)console.error('Stats équipe',error)}

