document.querySelector('#add-previous-players').addEventListener('click',async()=>{if(!db)return toast('Branche d’abord la base Supabase');const previous=game.winners[0]?.standings||[];if(!previous.length)return toast('Aucune liste précédente disponible');const existing=new Set(game.scores.map(x=>x.name.trim().toLowerCase())),names=previous.map(x=>String(x.name||'').trim()).filter(name=>name&&!existing.has(name.toLowerCase()));if(!names.length)return toast('Tous les participants précédents sont déjà présents');const button=document.querySelector('#add-previous-players');button.disabled=true;let added=0;for(const name of names){const{error}=await db.rpc('ajouter_joueur',{p_name:name});if(!error)added++}button.disabled=false;await refresh();toast(added?`${added} participant${added>1?'s':''} ajouté${added>1?'s':''} depuis la partie précédente`:'Aucun participant n’a pu être ajouté')});
