document.querySelector('#previous-winners').addEventListener('click',async event=>{const button=event.target.closest('[data-delete-game]');if(!button||!db||!isAdminName(operatorName))return;if(!confirm('Supprimer cette partie finalisée de l’historique ?'))return;const{error}=await db.rpc('admin_supprimer_partie_archivee',{p_winner_id:Number(button.dataset.deleteGame),p_requester_name:operatorName});if(error)return toast(error.message);await refresh();toast('Partie supprimée de l’historique')});
document.querySelector('#leaderboard').addEventListener('click',async event=>{const scoreButton=event.target.closest('[data-score-id]'),deleteButton=event.target.closest('[data-delete-score]');if(scoreButton){if(!requireName()||!db)return;scoreButton.disabled=true;const{error}=await db.rpc('modifier_points_jeu',{p_score_id:Number(scoreButton.dataset.scoreId),p_delta:Number(scoreButton.dataset.delta),p_operator_name:operatorName});if(error){scoreButton.disabled=false;return toast(error.message)}await refresh();return}if(deleteButton){if(!db)return;const player=game.scores.find(x=>String(x.id)===deleteButton.dataset.deleteScore);if(!player||!confirm(`Supprimer ${player.name} du classement ?`))return;const{error}=await db.rpc('supprimer_joueur',{p_score_id:player.id});if(error)return toast(error.message);await refresh();toast(`${player.name} supprimé`)}});
document.querySelector('#reset-game').addEventListener('click',async()=>{if(!db)return;const title=document.querySelector('#game-title').value.trim(),type=document.querySelector('#game-type').value;if(!title){document.querySelector('#game-title').focus();return toast('Donne obligatoirement un nom à la partie')};if(!game.scores.length)return toast('Ajoute au moins un participant');if(!confirm(`Finaliser et sauvegarder « ${title} » ? Le podium sera enregistré et le classement remis à zéro.`))return;const settingsResult=await db.rpc('configurer_jeu',{p_title:title,p_game_type:type});if(settingsResult.error)return toast(`Nom non enregistré : ${settingsResult.error.message}`);const{error}=await db.rpc('nouvelle_partie_jeu');if(error)return toast(`Sauvegarde impossible : ${error.message}`);await refresh();toast(`« ${title} » sauvegardée avec son podium`)});
document.querySelector('#reset-game-winners').addEventListener('click',async()=>{if(!db||!isAdminName(operatorName))return toast('Action réservée à Kai et Summer');if(!confirm('ATTENTION : supprimer définitivement TOUT l’historique des parties et TOUS les derniers gagnants ?'))return;const{error}=await db.rpc('admin_supprimer_historique_jeux',{p_requester_name:operatorName});if(error)return toast(`Suppression impossible : ${error.message}`);await refresh();toast('Tout l’historique des jeux a été supprimé')});
document.querySelector('#reset-orders').addEventListener('click',async()=>{if(!requireName())return;if(confirm('Effacer tes commandes locales et tes totaux partagés ?')){savedOrders=[];saveOrders();if(db){const{error}=await db.rpc('remettre_stats_personnelles_a_zero',{p_operator_name:operatorName});if(error)console.error(error);await refresh()}toast('Tes statistiques ont été remises à zéro')}});
document.querySelector('#order-history').addEventListener('click',async event=>{const button=event.target.closest('[data-order-cancel]');if(!button||!db)return;const index=savedOrders.findIndex(order=>String(order.date)===button.dataset.orderCancel);if(index<0)return;const order=savedOrders[index];if(!confirm(`Annuler cette commande de ${format(order.total)} ? Les totaux seront corrigés.`))return;const{error}=await db.rpc('annuler_commande_simple',{p_operator_name:order.operator||operatorName,p_revenue:order.total,p_items:order.items.length});if(error)return toast(error.message);savedOrders.splice(index,1);saveOrders();await refresh();toast('Commande annulée et totaux corrigés')});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-team-reset]');if(!button||!isAdminName(operatorName)||!db)return;const person=teamStats[Number(button.dataset.teamReset)];if(!person||!confirm(`Remettre les totaux de ${person.name} à zéro ?`))return;const{error}=await db.rpc('admin_remettre_stats_a_zero',{p_requester_name:operatorName,p_target_name:person.name});if(error)return toast(error.message);await refresh();toast(`Totaux de ${person.name} remis à zéro`)});
document.querySelector('#history').addEventListener('click',async event=>{const button=event.target.closest('[data-log-delete]');if(!button||!db)return;const item=state.history.find(row=>String(row.id)===button.dataset.logDelete);if(!item||!confirm(`Annuler « ${item.quantity>1?item.quantity+' × ':''}${item.name} » ? Le montant sera remis sur l’ardoise.`))return;button.disabled=true;const{error}=await db.rpc('annuler_ligne_ardoise',{p_log_id:item.id,p_requester_name:operatorName});if(error){button.disabled=false;return toast(error.message)}await refresh();toast('Ligne annulée et totaux corrigés')});
if(db){ db.channel('mojito-inn-live').on('postgres_changes',{event:'*',schema:'public',table:'ardoise_state'},refresh).on('postgres_changes',{event:'INSERT',schema:'public',table:'ardoise_logs'},payload=>{showRemoteAlert(payload.new);refresh()}).on('postgres_changes',{event:'UPDATE',schema:'public',table:'ardoise_logs'},refresh).on('postgres_changes',{event:'DELETE',schema:'public',table:'ardoise_logs'},refresh).on('postgres_changes',{event:'INSERT',schema:'public',table:'depenses'},payload=>{if(String(payload.new.operator_name).toLowerCase()!==operatorName.toLowerCase())showTeamAlert(`${payload.new.operator_name} a ajouté une dépense de ${format(payload.new.amount)}`,'addition','expenses');refresh()}).on('postgres_changes',{event:'UPDATE',schema:'public',table:'depenses'},refresh).on('postgres_changes',{event:'DELETE',schema:'public',table:'depenses'},refresh).on('postgres_changes',{event:'INSERT',schema:'public',table:'gifts'},payload=>{if(String(payload.new.operator_name).toLowerCase()!==operatorName.toLowerCase())showTeamAlert(`${payload.new.operator_name} a offert un cadeau à ${payload.new.beneficiary}`,'addition','gifts');refresh()}).on('postgres_changes',{event:'UPDATE',schema:'public',table:'gifts'},refresh).on('postgres_changes',{event:'DELETE',schema:'public',table:'gifts'},refresh).on('postgres_changes',{event:'*',schema:'public',table:'tombola_settings'},refresh).on('postgres_changes',{event:'*',schema:'public',table:'tombola_entries'},refresh).on('postgres_changes',{event:'*',schema:'public',table:'stats_equipe'},refresh).on('postgres_changes',{event:'*',schema:'public',table:'sales_events'},refresh).on('postgres_changes',{event:'*',schema:'public',table:'game_settings'},refresh).on('postgres_changes',{event:'*',schema:'public',table:'game_scores'},refresh).on('postgres_changes',{event:'*',schema:'public',table:'game_point_logs'},refresh).on('postgres_changes',{event:'INSERT',schema:'public',table:'game_winners'},payload=>{showTeamAlert(`Partie « ${payload.new.game_title} » finalisée`,'payment','games');refresh()}).on('postgres_changes',{event:'DELETE',schema:'public',table:'game_winners'},refresh).on('postgres_changes',{event:'INSERT',schema:'public',table:'bar_services'},payload=>{if(String(payload.new.opened_by).toLowerCase()!==operatorName.toLowerCase())showTeamAlert(`${payload.new.opened_by} a ouvert « ${payload.new.name} »`,'payment','service');refresh()}).on('postgres_changes',{event:'UPDATE',schema:'public',table:'bar_services'},payload=>{if(payload.new.status==='closed'){if(String(payload.new.closed_by).toLowerCase()!==operatorName.toLowerCase())showTeamAlert(`${payload.new.closed_by} a fermé « ${payload.new.name} »`,'addition','service');savedOrders=[];saveOrders()}refresh()}).subscribe(status=>{if(status==='SUBSCRIBED')syncStatus('Ardoise partagée · en direct','online')}); }
if(db){db.channel('mojito-balance-alerts').on('postgres_changes',{event:'UPDATE',schema:'public',table:'ardoise_state'},payload=>{const next=Number(payload.new.balance);if(state.balance>0&&next===0)showTeamAlert('L’ardoise est arrivée à zéro ✓','payment','tab');else if(state.balance>500&&next>0&&next<=500)showTeamAlert(`Ardoise bientôt vide · ${format(next)} restants`,'addition','tab')}).subscribe()}
updateMenuPrices();applyTheme(localStorage.getItem(THEME_KEY)||'sand');updateSoundButton();render(); renderCart();renderExpenses();renderGifts();renderOrderLogs();renderRaffle();renderCitizenSales();renderTeamStats();renderGame();renderPreviousWinners();renderServices(); refresh();setInterval(()=>{if(services.current)renderServices()},60000);setInterval(async()=>{if(db){const{data}=await db.rpc('fermer_service_si_inactif');if(data){await refresh();toast('Service fermé automatiquement après 4 h sans vente')}}},300000);openAccessGate();if((!db||sessionStorage.getItem(ACCESS_KEY)==='yes')&&!operatorName)setTimeout(openName,250);
